const incoming = items && items[0] && items[0].json ? items[0].json : {};
const body = incoming.body || incoming;
const state = body.conversation_state || {};
const message = String(body.message || body.text || body.request || '').trim();
const lower = message.toLowerCase();
const yesWords = ['si', 'sí', 'sii', 'claro', 'ok', 'dale', 'listo'];
const timeWords = ['corto', 'medio', 'largo'];

const options = [
  '1. EN-AGENT-001 - Bootstrap plataforma multiagente local. Base para conectar recomendacion, refinamiento, ejecucion, evidencia y revision.',
  '2. EN-EDGE-001 - Validar runtime Raspberry MQTT->DB. Desbloquea SENSOR -> TELEMETRY -> STORAGE.',
  '3. EN-QA-001 - Framework V&V y evidencia. Evita avanzar sin pruebas trazables.'
];

let primaryAgent = 'AGENT-BKL-001';
let workflow = 'WF-BACKLOG-RECOMMEND-001';
let reply = 'Puedo ayudarte a elegir, refinar o enrutar trabajo del proyecto.';
let nextQuestion = 'Quieres que te recomiende 3 opciones del backlog ahora?';
let nextState = { pending_intent: 'confirm_backlog_recommendation' };

if (yesWords.includes(lower) && state.pending_intent === 'confirm_backlog_recommendation') {
  reply = `Estas son las 3 opciones recomendadas:\n\n${options.join('\n\n')}`;
  nextQuestion = 'Cual opcion quieres tomar ahora: 1, 2 o 3?';
  nextState = { pending_intent: 'select_backlog_option' };
} else if (timeWords.includes(lower) && state.pending_intent === 'ask_available_time') {
  reply = `Perfecto, tomo tiempo ${lower}. Estas son las 3 opciones recomendadas:\n\n${options.join('\n\n')}`;
  nextQuestion = 'Cual opcion quieres tomar ahora: 1, 2 o 3?';
  nextState = { pending_intent: 'select_backlog_option', available_time: lower };
} else if (['1', '2', '3'].includes(lower) && state.pending_intent === 'select_backlog_option') {
  const selected = lower === '1' ? 'EN-AGENT-001' : lower === '2' ? 'EN-EDGE-001' : 'EN-QA-001';
  primaryAgent = 'AGENT-REF-001';
  workflow = 'WF-REFINE-STORY-001';
  reply = `Seleccionaste ${selected}. Antes de ejecutar, debe pasar por refinamiento granular.`;
  nextQuestion = `Confirmas que refinamos ${selected}?`;
  nextState = { pending_intent: 'confirm_refine_story', selected_backlog_id: selected };
} else if (yesWords.includes(lower) && state.pending_intent === 'confirm_refine_story') {
  primaryAgent = 'AGENT-REF-001';
  workflow = 'WF-REFINE-STORY-001';
  reply = `Listo. Enruto ${state.selected_backlog_id || 'la HU seleccionada'} al Refinement Agent.`;
  nextQuestion = 'Quieres que el refinamiento sea corto o detallado?';
  nextState = { pending_intent: 'ask_refinement_depth', selected_backlog_id: state.selected_backlog_id };
} else if ((lower === 'hu' || lower === 'historia' || lower === 'enabler') && state.pending_intent === 'ask_refine_target') {
  primaryAgent = 'AGENT-REF-001';
  workflow = 'WF-REFINE-STORY-001';
  reply = 'Perfecto, vamos a refinar una HU o enabler.';
  nextQuestion = 'Dime el ID exacto, por ejemplo EN-AGENT-001, EN-EDGE-001 o HU-SOIL-001.';
  nextState = { pending_intent: 'ask_refine_target_id' };
} else if (/^(hu|en|exp)-[a-z0-9]+-\d+/i.test(lower) || /^en-agent-001$/i.test(lower)) {
  primaryAgent = 'AGENT-REF-001';
  workflow = 'WF-REFINE-STORY-001';
  const selected = message.toUpperCase();
  reply = `Entendido. Vamos a refinar ${selected}.`;
  nextQuestion = 'Quieres un refinamiento corto o detallado?';
  nextState = { pending_intent: 'ask_refinement_depth', selected_backlog_id: selected };
} else if (lower.includes('refinar') || lower.includes('refinamiento')) {
  primaryAgent = 'AGENT-REF-001';
  workflow = 'WF-REFINE-STORY-001';
  reply = 'Entendido. Voy a tratar esto como una solicitud de refinamiento de HU o enabler.';
  nextQuestion = 'Que HU o enabler quieres refinar? Puedes decir EN-AGENT-001, EN-EDGE-001 o HU-SOIL-001.';
  nextState = { pending_intent: 'ask_refine_target' };
} else if (lower.includes('siguiente') || lower.includes('backlog') || lower.includes('trabajar') || lower.includes('recomienda')) {
  reply = 'Entendido. La ruta correcta es pedir recomendacion al Backlog Agent usando prioridad, WIP y modo de trabajo.';
  nextQuestion = 'Cuanto tiempo tienes ahora: corto, medio o largo?';
  nextState = { pending_intent: 'ask_available_time' };
} else if (lower.includes('arquitectura') || lower.includes('decision') || lower.includes('decisión')) {
  primaryAgent = 'AGENT-ARCH-001';
  workflow = 'WF-ARCH-REVIEW-001';
  reply = 'Entendido. Esto debe ir a revision arquitectonica o decision tecnica.';
  nextQuestion = 'Cual es la decision o cambio arquitectonico que quieres evaluar?';
  nextState = { pending_intent: 'ask_architecture_topic' };
} else if (lower.includes('mercado') || lower.includes('contenido') || lower.includes('growth')) {
  primaryAgent = lower.includes('contenido') || lower.includes('growth') ? 'AGENT-GROW-001' : 'AGENT-MKT-001';
  workflow = 'WF-MARKET-GROWTH-001';
  reply = 'Entendido. Esto debe pasar por mercado/growth respetando la politica de claims.';
  nextQuestion = 'Quieres trabajar mercado, contenido educativo o validacion de claims?';
  nextState = { pending_intent: 'ask_market_growth_topic' };
}

return [{
  json: {
    chat_id: body.chat_id || 'local-project-chat',
    received_message: message,
    status: 'SUCCESS',
    reply,
    route: { workflow, primary_agent: primaryAgent, authority: 'A1', review_required: true },
    constraints: [
      'No modificar HU congeladas.',
      'No mover estados sin aprobacion humana.',
      'No marcar DONE sin evidencia.',
      'Hacer una sola pregunta al humano por turno.'
    ],
    next_question: nextQuestion,
    conversation_state: nextState,
    suggested_payloads: {
      backlog_recommendation: { message: 'recomienda siguiente trabajo', available_time: 'unknown', preferred_mode: 'any' },
      refine_story: { message: 'refinar EN-AGENT-001', backlog_id: 'EN-AGENT-001' }
    }
  }
}];
